// TestImportaciones_ListarYVer comprueba GET /api/importaciones y GET /api/importaciones/{id}:
// piden solo sesion, el listado trae el resumen y la ficha trae todas las incidencias.
func TestImportaciones_ListarYVer(t *testing.T) {
	e := nuevoCatalogoImportado(t)

	if r := pedirAPI(t, e.srv, "GET", "/api/importaciones", nil, ""); r.estado != 401 {
		t.Fatalf("listar sin sesion: estado %d, se esperaba 401", r.estado)
	}

	var lista struct {
		Items []struct {
			ID           int64  `json:"id"`
			Estado       string `json:"estado"`
			Creados      int    `json:"creados"`
			Actualizados int    `json:"actualizados"`
			Omitidos     int    `json:"omitidos"`
			Observados   int    `json:"observados"`
		} `json:"items"`
		Total int `json:"total"`
	}
	r := e.pedir(t, "GET", "/api/importaciones", nil)
	if r.estado != 200 {
		t.Fatalf("listar: estado %d: %s", r.estado, r.cuerpo)
	}
	if err := json.Unmarshal(r.cuerpo, &lista); err != nil {
		t.Fatal(err)
	}
	if lista.Total < 1 || len(lista.Items) < 1 {
		t.Fatalf("el listado no trae la corrida recien hecha: %s", r.cuerpo)
	}
	primera := lista.Items[0]
	if primera.Estado != "completada" || primera.Creados == 0 {
		t.Errorf("resumen inesperado: %+v", primera)
	}

	var ficha struct {
		ID          int64 `json:"id"`
		Incidencias []struct {
			Tipo    string `json:"tipo"`
			Mensaje string `json:"mensaje"`
		} `json:"incidencias"`
	}
	r = e.pedir(t, "GET", fmt.Sprintf("/api/importaciones/%d", primera.ID), nil)
	if r.estado != 200 {
		t.Fatalf("ver: estado %d: %s", r.estado, r.cuerpo)
	}
	if err := json.Unmarshal(r.cuerpo, &ficha); err != nil {
		t.Fatal(err)
	}
	if ficha.ID != primera.ID || len(ficha.Incidencias) == 0 {
		t.Errorf("la ficha no trae sus incidencias: %s", r.cuerpo)
	}

	if r := e.pedir(t, "GET", "/api/importaciones/999999999", nil); r.estado != 404 {
		t.Errorf("importacion inexistente: estado %d, se esperaba 404", r.estado)
	}
}
